    finished = []
    return finished

hcw-software.solution:
def finish_order(work, slice):
    left = dict(work)
    finished = []
    while left:
        for name in list(left):
            left[name] -= min(slice, left[name])
            if left[name] == 0:
                finished.append(name)
                del left[name]
    return finished

